package com.rikkeibank.account.controller; import com.rikkeibank.account.dto.*; import com.rikkeibank.account.service.BankAccountService; import jakarta.validation.Valid; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/internal/accounts") public class InternalAccountController{private final BankAccountService s;private final String key;public InternalAccountController(BankAccountService s,@Value("${app.internal-key}") String key){this.s=s;this.key=key;}private void verify(String supplied){if(!key.equals(supplied))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Invalid internal key");}@PostMapping("/debit") public AccountBalanceResponse debit(@RequestHeader("X-Internal-Key") String k,@Valid @RequestBody AccountOperationRequest r){verify(k);return s.debit(r);}@PostMapping("/credit") public AccountBalanceResponse credit(@RequestHeader("X-Internal-Key") String k,@Valid @RequestBody AccountOperationRequest r){verify(k);return s.credit(r);}@PostMapping("/compensate-debit") public AccountBalanceResponse compensateDebit(@RequestHeader("X-Internal-Key") String k,@Valid @RequestBody AccountOperationRequest r){verify(k);return s.compensateDebit(r);}@PostMapping("/compensate-credit") public AccountBalanceResponse compensateCredit(@RequestHeader("X-Internal-Key") String k,@Valid @RequestBody AccountOperationRequest r){verify(k);return s.compensateCredit(r);}}
